import json

with open('inventory.json') as f:
    inv = {sku: int(qty) for sku, qty in json.load(f).items()}

rejected = []
with open('transactions.txt') as f:
    lines = f.read().split('\n')

for i, line in enumerate(lines, 1):
    parts = line.split()
    if not parts:
        continue
    op, sku, qty = parts[0].lower(), parts[1], int(parts[2])
    if op == 'add':
        inv[sku] = inv.get(sku, 0) + qty
    elif op == 'remove':
        if sku not in inv or inv[sku] - qty < 0:
            rejected.append(i)
        else:
            inv[sku] -= qty
    else:
        rejected.append(i)

with open('inventory_after.json', 'w') as f:
    json.dump(inv, f, indent=2)
    f.write('\n')

with open('rejected.txt', 'w') as f:
    for n in rejected:
        f.write(f'{n}\n')

print('inventory:', inv)
print('rejected:', rejected)
print('transaction lines:', len([l for l in lines if l.strip()]))
